function Pin($p){[ordered]@{path=$p;bytes=(Get-Item $p).Length;sha256=(Get-FileHash $p).Hash}}
function Check($p){if((Get-FileHash $p.path).Hash -ne $p.sha256 -or ($p.bytes -and (Get-Item $p.path).Length -ne $p.bytes)){throw ('Pin drift: '+$p.path)}}
$cp=Join-Path $logs 'r455-candidate.json';$c=Get-Content $cp -Raw|ConvertFrom-Json;Check $c
foreach($p in $c.source_pins){Check $p;if((Get-FileHash $p.snapshot).Hash -ne $p.sha256){throw 'Current source snapshot drift'}}
$build=@(Get-Content (Join-Path $logs "$Revision-library-build.jsonl")|ForEach-Object{try{$_|ConvertFrom-Json}catch{}})
if(-not @($build|Where-Object{$_.reason -eq 'build-finished' -and $_.success}).Count){throw 'Library build failed'}
$libs=@($build|Where-Object{$_.reason -eq 'compiler-artifact' -and $_.target.name -eq 'lito_modern'}|ForEach-Object{$_.filenames}|Where-Object{$_ -like '*.rlib'});if($libs.Count -ne 1){throw 'Library count'}
$lib=Join-Path (Split-Path $c.path -Parent) 'r455-production.rlib';if(Test-Path $lib){throw 'Already sealed'};[IO.File]::Copy($libs[0],$lib,$false);if((Get-FileHash $lib).Hash -ne (Get-FileHash $libs[0]).Hash){throw 'Lib copy drift'};$c|Add-Member production_library (Pin $lib)
