if($d.runtime_inputs_observed -or $d.renderer_LOADED -or $d.GUI -ne 0 -or $d.new_CPU_images -ne 0){throw 'Clock guard scope differs'}
$ap=Join-Path $logs 'r455-original-source-pins.json';$asm=Get-Content $ap -Raw|ConvertFrom-Json;Check $asm.original_disassembly;$text=[IO.File]::ReadAllText($asm.original_disassembly.path);foreach($p in $asm.files){Check $p;if(!$text.Contains([IO.File]::ReadAllText($p.path))){throw 'ASM not exact'}}
$snap=Get-Content (Join-Path $logs 'r439-appearance-snapshot.json') -Raw|ConvertFrom-Json;if((Get-FileHash (Join-Path $snap.candidate.root 'manifest.json')).Hash -ne $snap.candidate.manifest_sha256){throw 'Appearance manifest drift'}
$resources=@(foreach($name in $d.input_pins.PSObject.Properties.Name){$p=Pin (Join-Path $snap.candidate.root $name);if($p.sha256 -ne $d.input_pins.$name.sha256 -or $p.bytes -ne $d.input_pins.$name.bytes){throw 'Input drift'};$p});foreach($p in $d.extra_input_pins){Check $p}
& (Join-Path $PSScriptRoot 'audit-continuation-source-scope.ps1')
$scopePath=Join-Path (Split-Path $c.path -Parent) 'source-change-scope-524.json';[IO.File]::Copy((Join-Path $logs 'source-change-scope.json'),$scopePath,$false)
$c.validation='PASSED new meaningful focused settled actor roof clock-write guard; current source/host/lib/source inputs frozen; previous CPU state evidence preserved';Write-ModernEvidenceJson -Path $cp -Value $c
$result=Join-Path $logs 'r455-finite-renderer-result.json';Write-ModernEvidenceJson -Path $result -Value ([ordered]@{state='PASSED_FINITE_ROOF_CLOCK_WRITE_GUARD';candidate=$c;focused_passed=1;focused_failed=0;test=Pin $test;details=Pin $dp;ASM=Pin $ap;original_fragments=$asm.files.Count;selected_resources=$resources;extra_inputs=$d.extra_input_pins;immutable_source_scope=Pin $scopePath;source_files=524;renderer_LOADED=$false;GUI=0;original_BIN_executed=$false})
