$stages=@(foreach($stage in @('r452','r453','r454','r455')){$rp=Join-Path $logs "$stage-finite-renderer-result.json";$r=Get-Content $rp -Raw|ConvertFrom-Json;Check $r.candidate;Check $r.candidate.production_library;foreach($source in $r.candidate.source_pins){if((Get-FileHash $source.snapshot).Hash -ne $source.sha256){throw 'Historical source snapshot drift'}};foreach($p in @($r.images)+@($r.selected_resources)+@($r.extra_inputs)){if($null -ne $p){Check $p}};Check $r.details;Check $r.ASM;Check $r.immutable_source_scope;[ordered]@{stage=$stage;record=Pin $rp;final=Pin (Join-Path $logs "$stage-final-verification.json");source_snapshots=$r.candidate.source_pins.Count;original_fragments=$r.original_fragments;focused_passed=1;CPU_images=$(if($null -eq $r.images){0}else{@($r.images).Count})}})
