$protected=@(foreach($stage in @('r447','r448','r449','r450','r451')){$p=Join-Path $logs "$stage-candidate.json";$old=Get-Content $p -Raw|ConvertFrom-Json;Check $old;Check $old.production_library;foreach($source in $old.source_pins){if((Get-FileHash $source.snapshot).Hash -ne $source.sha256){throw 'Older immutable source drift'}};Pin $p})
